?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>دخول الإدارة | أصل المتصدر</title><link rel="stylesheet" href="/assets/css/app.css"><style>body{min-height:100vh;display:grid;place-items:center;background:#f4f7fa}.login{width:min(420px,calc(100% - 28px));background:#fff;padding:32px;border:1px solid #e5eaf0;border-radius:16px;box-shadow:0 20px 60px #10263f12}.login h1{color:#10263f;font-size:24px}.login button{width:100%;margin-top:18px}.error{color:#a33;background:#fff1f1;padding:10px;border-radius:8px;font-size:13px}</style></head><body><form class="login" method="post"><a class="brand" href="/"><span class="brand-mark">م</span><span><b>أصل المتصدر</b><small>بوابة الإدارة</small></span></a><h1>تسجيل الدخول</h1><p class="muted">أدخل بيانات حسابك الإداري.</p><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><label>اسم المستخدم<input name="username" autocomplete="username" required></label><label>كلمة المرور<input type="password" name="password" autocomplete="current-password" required></label><button class="btn btn-primary" type="submit">دخول آمن</button></form></body></html>
